def make_audio_guides(P,C,G,S,W,B,N,L):
 return [G('audio-pipeline','Full audio pipeline','Inside a call','CLI + browser',
 'How do microphone, file, and URL audio become a call I can hear?',
 'Explore source selection → PCM → echo cancellation and spectral DSP → Opus → transport → mix-minus → playback, with browser and recording branches.',
 'Locate every audio boundary, distinguish microphone processing from media injection, and understand what volume and processing options actually change.',
 'Start with the selected source and its PCM queue. Then inspect 480-sample AEC blocks, 960-sample Opus frames, packet receipt, recipient mixing, and playback underruns. Compare render-reference audio with capture when diagnosing echo; raising --volume cannot repair missing packets.',[
 C('sources','Choose what is audible','Microphone, media, both, and test audio are different source policies; speaker gain is a separate control.',
 P(L+'options/registry/audio.c',None,'Resolve audio options','--audio-capture-source selects auto/mic/media/both/remote. --microphone-volume (alias --ivolume) controls microphone sensitivity; --volume aliases --speakers-volume. The registry also defines device and spectral options.'),
 P('src/client/audio.c','audio_client_init','Build the native client pipeline','Initialization examines whether the selected media source has audio, creates the processing context, and attaches it to device audio. Media-aware codec configuration differs from speech-only capture.',L+'audio/client_pipeline.cpp'),
 P(L+'audio/audio.c','audio_worker_thread','Select mic, media, or both','Media-only input is paced by elapsed time at 48 kHz and placed in the capture queue. Microphone samples use the duplex processing branch. Test-audio changes source selection and bypasses normal microphone capture.')),
 C('decode','File or URL → PCM','FFmpeg decodes native media; URL resolution precedes decoding. These samples do not inherently traverse microphone AEC3.',
 P(L+'media/source.c',None,'Resolve --file and --url','The media-source abstraction selects native file/stream decoding and resolves complex URLs through yt-dlp where needed. Video and audio readers share source ownership.',L+'media/yt_dlp.c',L+'media/ffmpeg_decoder.c'),
 P(L+'media/ffmpeg_decoder.c','ffmpeg_decoder_create','Open and normalize media','libavformat discovers streams, libavcodec decodes, and libswresample converts audio to mono floating-point 48 kHz PCM. Opening video successfully does not imply an audio stream exists.'),
 P(L+'media/source.c','media_source_read_audio','Read decoded audio','This boundary supplies PCM rather than compressed Opus. FFmpeg reads/decodes audio frames, buffers partial reads, converts sample format/rate, and flushes resampler output at end of stream.',L+'media/ffmpeg_decoder.c')),
 C('devices','Devices, queues, and source mixing','PortAudio callbacks and a worker decouple device clocks from DSP and network writes.',
 P(L+'audio/audio.c','input_callback','Normalize device input','Input callbacks feed raw capture buffers; device-rate conversion places microphone samples in the fixed 48 kHz processing domain. Separate input/output streams and duplex mode have distinct callback paths.'),
 P(L+'audio/audio.c','audio_worker_thread','Process complete blocks','The worker pairs complete 480-sample/10 ms capture and render blocks for AEC3. With no complete playback reference it uses silence so microphone capture can progress; partial capture remains buffered.',L+'audio/client_pipeline.cpp'),
 P(L+'audio/audio.c','audio_publish_local_capture','Add media after microphone DSP','Processed microphone audio is recorded/visualized, then optional decoded media is added with clipping before publishing capture PCM. Thus media injected with both sources bypasses microphone AEC/spectral processing. Mirror can monitor media locally.',L+'audio/recording.c',L+'audio/visualization.c')),
 C('aec','AEC3 and the actual speaker reference','Acoustic echo cancellation removes speaker leakage into the microphone; host mix-minus solves a different feedback path.',
 P(L+'audio/client_pipeline.cpp','client_audio_pipeline_create','Construct WebRTC AEC3','Persistent WebRTC AudioBuffers and the echo controller are created and warmed up. Processing configuration also installs filters and optional spectral state. Follow this complete reference for flags and failure cleanup.'),
 P(L+'audio/client_pipeline.cpp','client_audio_pipeline_process_duplex','Render first, then capture','The controller consumes playback reference and microphone capture in 10 ms blocks, converts between normalized float and WebRTC sample ranges, processes capture, and reports echo metrics. BYPASS_AEC3 changes the diagnostic path; it is not a normal volume setting.'),
 P(L+'audio/audio.c','output_callback','Reference what really plays','Playback volume is applied at output; the render reference stays in the 48 kHz pipeline domain even when the physical output rate differs. Decoding a packet is too early to establish which audio actually reached the speaker.',L+'audio/client_pipeline.cpp')),
 C('spectral','Inside spectral.c','Opt-in FFTW processing follows AEC3 and precedes Opus; its streaming windows add their own state and latency.',
 P(L+'audio/client_pipeline.cpp','client_audio_pipeline_create','Gate the spectral branch','--audio-spectral enables creation unless test-audio is active. --audio-fft-size accepts 512/1024/2048. Spectral AGC disables the ordinary AGC flag; multiband compression disables ordinary compression to avoid applying both.',L+'audio/spectral.c',L+'options/registry/audio.c'),
 P(L+'audio/spectral.c','spectral_process','Stream through overlapping windows','Samples accumulate in hop-sized blocks (FFT size/4). The ready queue emits prior overlap-add output while a new FFT frame accumulates; non-finite input is replaced with zero. Reset/recreation matters when investigating startup behavior.',L+'audio/spectral.c'),
 P(L+'audio/spectral.c','process_frame','Transform, shape, and reconstruct','A Hann window feeds FFTW. Per-bin adaptive gating, four-band compression, bounded adaptive EQ, spectral AGC, and optional experimental pitch correction modify the spectrum. Inverse FFT and normalized Hann overlap-add reconstruct PCM. Back in process_duplex, remaining ordinary AGC, high/low-pass filters, gate, and compressor run in that order.',L+'audio/client_pipeline.cpp')),
 C('opus','PCM → Opus → packets','Codec framing and network batching are separate from capture processing.',
 P('src/client/audio.c','audio_capture_thread_func','Accumulate complete Opus frames','The native capture worker drains processed PCM, accumulates 20 ms/960-sample frames, encodes them, and builds outgoing batches. Queueing separates capture timing from network backpressure.',L+'audio/client_pipeline.cpp'),
 P(L+'audio/client_pipeline.cpp','client_audio_pipeline_capture','Encode without repeating DSP','opus_encode_float consumes already-processed capture samples. Encoding must not run AEC3 or spectral processing a second time. Configuration selects media AUDIO/128 kbps versus microphone VOIP/32 kbps defaults.'),
 P('src/client/audio.c','audio_sender_thread_func','Send queued batches','The sender removes batches from its queue and sends through the client transport helpers. Opus compression does not provide encryption; framing, security, and TCP/WebSocket/WebRTC transport are separate layers.','src/client/server.c',L+'network/acip/send.c')),
 C('mix','Host decode and mix-minus','A media host turns participant streams into receiver-specific output; dedicated server and shared session hosts have separate implementations.',
 P('src/server/render.c','client_audio_render_thread','Prepare dedicated-server output','The server audio worker builds a recipient mix, excludes that recipient’s own contribution, encodes Opus, and sends it. Follow the mixer dependency for buffering and gain policy.',L+'audio/mixer.c'),
 P(S+'audio.c','session_audio_mix_excluding','Mix shared-session sources','Shared session audio drains active source buffers, skips exclude_id, combines samples and scales the mix. This source exclusion cannot cancel physical speaker leakage into another microphone.'),
 P(S+'host.c',None,'Bridge shared host protocol and audio','The shared host validates incoming audio, decodes Opus into per-participant PCM, and encodes outgoing mixes using its own codec settings. Do not assume the client media encoder bitrate applies to host output.',S+'audio.c',L+'audio/opus.c')),
 C('playback','Receive, decode, volume, and speakers','An arriving packet still needs valid frame sizes, decoded PCM, buffered pacing, and a functioning output stream.',
 P(S+'protocol.c','receive_opus_batch','Validate and decode incoming batches','The shared protocol validates the entire batch before invoking adapter callbacks to decode frames and deliver PCM. The native adapter also attempts packet-loss concealment when Opus decoding fails.','src/client/protocol_adapter.c','src/client/audio.c'),
 P('src/client/audio.c','audio_process_received_samples','Publish received PCM','Receive processing tracks levels and queues samples for device playback. Buffer depth affects latency; hearing nothing can mean no received PCM or an output queue that is not being drained.',L+'audio/audio.c'),
 P(L+'audio/audio.c','duplex_callback','Apply --volume at playback','--volume/--speakers-volume is clamped to 0–1 and scales output samples; --microphone-volume scales captured microphone samples in the worker. The played signal also supplies the echo reference. Live =/- controls change playback gain, not the Opus bitrate.',S+'keyboard_handler.c')),
 C('browser','Browser audio takes its own path','TypeScript owns Web Audio and browser devices; native PortAudio/AEC3/spectral execution is not implied by sharing a C Opus codec.',
 P(W+'audio/AudioPipeline.ts','AudioPipeline','Own Web Audio routing','The browser requests echoCancellation/noiseSuppression/autoGainControl from getUserMedia, uses gain nodes and device selection, and routes received PCM to playback. Browser-managed processing differs from native client_pipeline.cpp.',W+'wasm/AVState.ts'),
 P(W+'audio/OpusEncoder.ts','OpusEncoder','Cross the C/WASM codec boundary','Browser PCM uses the C Opus exports through this adapter. Follow encode/decode ownership and buffer allocation independently of native device processing.',L+'audio/opus.c'),
 P(W+'audio/playback-worklet.js',None,'Drain queued browser audio','The worklet consumes queued PCM and reports underruns. AudioPipeline owns startup/recovery buffering and output gain; local browser media playback is also used by the file preview path.',W+'audio/AudioPipeline.ts',W+'hooks/useMirrorFile.ts')),
 C('recording','A/V scheduling, recording, and teardown','The file named pipeline.c is the video scheduling pipeline; audio processing, recording taps, and FFmpeg output have their own owners.',
 P(S+'pipeline.c','session_pipeline_create','Locate the video pipeline','Capture, display, and optional encode queues move video frames between threads. This pipeline is not the AEC3/FFT/Opus DSP chain. Its encode thread passes captured timestamps to display/render-file encoding.',S+'display.c'),
 P(L+'audio/recording.c',None,'Inspect timestamped audio taps','Microphone/media/playback recording submissions preserve source identity and timing. Recording policy and draining determine which audio reaches a recording, independently of what an individual speaker hears.',L+'audio/audio.c',L+'media/ffmpeg_encoder.c'),
 P('src/client/audio.c','audio_cleanup','Release workers and codec state','Stop capture/sending and device use before destroying processing state and queues. FFmpeg decoding input, Opus call encoding, and FFmpeg recording output are three different jobs.',L+'audio/client_pipeline.cpp',L+'audio/audio.c'))
 ],['audio','media','settings','recording'])]
